<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule; use Illuminate\Http\Client\Pool; use Illuminate\Http\Client\Response; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Pterodactyl\Facades\Activity; use Illuminate\Http\Client\ConnectionException; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustPluginsRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustPluginsDeleteRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustPluginsReloadRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustPluginsToggleRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustPluginsInstallRequest; class RustPluginController extends ClientApiController { private const DISABLED = '.disabled'; private const NAME = '/^[A-Za-z0-9_]{1,64}$/'; private const AGENT = 'Pterodactyl-Stark/1.0 (rust plugin manager)'; private const UMOD = 'https://umod.org'; private const SORTS = ['downloads', 'latest_release_at', 'created_at', 'title', 'watchers']; private const MAX_PLUGIN_BYTES = 2_097_152; public function index(RustPluginsRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $layout = $this->layout($server); $entries = $files->listFiles($layout['directory']); if ($entries === null) { return new JsonResponse($layout + ['available' => false, 'running' => false, 'plugins' => []]); } $configs = []; foreach ($files->listFiles($layout['configDirectory']) ?? [] as $entry) { if (!$entry['directory'] && str_ends_with(mb_strtolower($entry['name']), '.json')) { $configs[mb_substr($entry['name'], 0, -5)] = true; } } $plugins = []; foreach ($entries as $entry) { $file = $entry['name']; if ($entry['directory'] || ($name = $this->pluginName($file)) === null) { continue; } $header = $this->header($files, $server, $layout['directory'] . '/' . $file, $entry); $plugins[] = [ 'file' => $file, 'name' => $name, 'title' => $header['title'] ?: $name, 'author' => $header['author'], 'version' => $header['version'], 'description' => $header['description'], 'size' => (int) $entry['size'], 'modifiedAt' => $entry['modified_at'], 'disabled' => str_ends_with(mb_strtolower($file), self::DISABLED), 'config' => isset($configs[$name]) ? $layout['configDirectory'] . '/' . $name . '.json' : null, ]; } $catalogue = $this->lookup(array_column($plugins, 'name')); foreach ($plugins as &$plugin) { $known = $catalogue[$plugin['name']] ?? null; $plugin['icon'] = $known['icon'] ?? null; $plugin['url'] = $known['url'] ?? null; $plugin['latest'] = $known['version'] ?? null; $plugin['description'] = $plugin['description'] ?: ($known['description'] ?? ''); $plugin['updatable'] = $known !== null && $plugin['version'] !== null && $known['version'] !== null && version_compare($this->numeric($known['version']), $this->numeric($plugin['version']), '>'); } unset($plugin); usort($plugins, fn (array $a, array $b) => strcasecmp($a['title'], $b['title'])); return new JsonResponse($layout + [ 'available' => true, 'running' => $files->powerStateOrNull() === 'running', 'plugins' => $plugins, ]); } public function search(RustPluginsRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'query' => ['present', 'nullable', 'string', 'max:100'], 'page' => ['nullable', 'integer', 'min:1', 'max:200'], 'sort' => ['nullable', 'string', Rule::in(self::SORTS)], ]); $query = trim((string) ($data['query'] ?? '')); $page = (int) ($data['page'] ?? 1); $sort = (string) ($data['sort'] ?? 'downloads'); try { $payload = Cache::remember('rust-plugins:search:' . md5("{$query}|{$page}|{$sort}"), 600, function () use ($query, $page, $sort) { $response = Http::withHeaders(['User-Agent' => self::AGENT, 'Accept' => 'application/json']) ->timeout(10) ->connectTimeout(5) ->get(self::UMOD . '/plugins/search.json', [ 'query' => $query, 'page' => $page, 'sort' => $sort, 'sortdir' => $sort === 'title' ? 'asc' : 'desc', 'categories' => 'universal,rust', ]); if ($response->failed() || !is_array($response->json('data'))) { throw new ConnectionException('uMod answered ' . $response->status()); } return [ 'results' => array_values(array_filter(array_map($this->hit(...), $response->json('data')))), 'page' => (int) $response->json('current_page', $page), 'pages' => max(1, (int) $response->json('last_page', 1)), 'total' => (int) $response->json('total', 0), ]; }); } catch (ConnectionException) { return $this->unreachable(); } return new JsonResponse($payload); } public function install(RustPluginsInstallRequest $request, Server $server): JsonResponse { $data = $request->validate(['name' => ['required', 'string', 'regex:' . self::NAME]]); $name = $data['name']; $files = new ServerFiles($server); $layout = $this->layout($server); $entries = $files->listFiles($layout['directory']); if ($entries === null) { return $this->error('NoFramework', "There is no {$layout['directory']} folder. Set the modding framework on the Startup page and restart the server once.", 422); } try { $response = Http::withHeaders(['User-Agent' => self::AGENT]) ->timeout(20) ->connectTimeout(5) ->get(self::UMOD . "/plugins/{$name}.cs"); } catch (ConnectionException) { return $this->unreachable(); } $source = $response->successful() ? $response->body() : ''; if ($source === '' || strlen($source) > self::MAX_PLUGIN_BYTES || !preg_match('/\bclass\s+' . $name . '\b/', $source)) { return $this->error('NotAPlugin', "uMod has no plugin called {$name}.", 404); } $present = array_column($entries, 'name'); $file = in_array("{$name}.cs" . self::DISABLED, $present, true) && !in_array("{$name}.cs", $present, true) ? "{$name}.cs" . self::DISABLED : "{$name}.cs"; if (!$files->writeFile($layout['directory'] . '/' . $file, $source)) { return $this->error('WriteFailed', 'The node would not save the plugin.', 502); } Activity::event('server:rust-plugin.install')->property(['plugin' => $name, 'file' => $file])->log(); return new JsonResponse(['installed' => true, 'file' => $file, 'disabled' => $file !== "{$name}.cs"]); } public function toggle(RustPluginsToggleRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:100']]); $from = $data['file']; if ($this->pluginName($from) === null) { return $this->notAPlugin(); } $to = str_ends_with(mb_strtolower($from), self::DISABLED) ? mb_substr($from, 0, -mb_strlen(self::DISABLED)) : $from . self::DISABLED; if (!(new ServerFiles($server))->renamePath($this->layout($server)['directory'], $from, $to)) { return $this->error('RenameFailed', 'That could not be changed.', 502); } Activity::event('server:rust-plugin.toggle')->property(['from' => $from, 'to' => $to])->log(); return new JsonResponse(['file' => $to, 'disabled' => str_ends_with($to, self::DISABLED)]); } public function reload(RustPluginsReloadRequest $request, Server $server): JsonResponse { $data = $request->validate(['name' => ['required', 'string', 'regex:' . self::NAME]]); $files = new ServerFiles($server); if ($files->powerStateOrNull() !== 'running') { return $this->error('NotRunning', 'The server has to be running to reload a plugin.', 409); } $command = $this->layout($server)['framework'] === 'carbon' ? 'c.reload' : 'oxide.reload'; $files->sendCommand("{$command} {$data['name']}"); return new JsonResponse(['reloaded' => true]); } public function destroy(RustPluginsDeleteRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:100']]); $file = $data['file']; if ($this->pluginName($file) === null) { return $this->notAPlugin(); } if (!(new ServerFiles($server))->deletePaths($this->layout($server)['directory'], [$file])) { return $this->error('DeleteFailed', 'That could not be removed.', 502); } Activity::event('server:rust-plugin.delete')->property('file', $file)->log(); return new JsonResponse(['deleted' => true]); } private function layout(Server $server): array { $configured = mb_strtolower(trim((string) ($server->variables()->where('env_variable', 'FRAMEWORK')->first()?->server_value ?? ''))); $carbon = $configured === 'carbon'; return [ 'framework' => $carbon ? 'carbon' : 'oxide', 'configured' => in_array($configured, ['vanilla', 'oxide', 'carbon'], true) ? $configured : null, 'directory' => $carbon ? '/carbon/plugins' : '/oxide/plugins', 'configDirectory' => $carbon ? '/carbon/configs' : '/oxide/config', ]; } private function pluginName(string $file): ?string { if ($file !== basename($file) || !preg_match('/^([A-Za-z0-9_]{1,64})\.cs(\.disabled)?$/', $file, $match)) { return null; } return $match[1]; } private function header(ServerFiles $files, Server $server, string $path, array $entry): array { $key = 'rust-plugins:header:' . $server->uuid . ':' . md5($path . '|' . $entry['size'] . '|' . $entry['modified_at']); return Cache::remember($key, 604800, function () use ($files, $path) { $source = $files->fileContents($path, 1_048_576) ?? ''; $info = []; preg_match('/\[Info\(\s*"((?:[^"\\\\]|\\\\.)*)"\s*,\s*"((?:[^"\\\\]|\\\\.)*)"\s*,\s*"?([0-9][0-9.]*)"?/', $source, $info); preg_match('/\[Description\(\s*"((?:[^"\\\\]|\\\\.)*)"/', $source, $description); return [ 'title' => isset($info[1]) ? mb_substr(stripcslashes($info[1]), 0, 100) : '', 'author' => isset($info[2]) ? mb_substr(stripcslashes($info[2]), 0, 100) : null, 'version' => $info[3] ?? null, 'description' => isset($description[1]) ? mb_substr(stripcslashes($description[1]), 0, 300) : '', ]; }); } private function lookup(array $names): array { $names = array_values(array_unique(array_filter($names, fn ($name) => preg_match(self::NAME, $name) === 1))); $found = []; $missing = []; foreach ($names as $name) { $cached = Cache::get("rust-plugins:umod:{$name}"); if ($cached === null) { $missing[] = $name; } elseif ($cached !== false) { $found[$name] = $cached; } } foreach (array_chunk($missing, 12) as $batch) { try { $responses = Http::pool(fn (Pool $pool) => array_map( fn (string $name) => $pool->as($name) ->withHeaders(['User-Agent' => self::AGENT, 'Accept' => 'application/json']) ->timeout(6) ->connectTimeout(4) ->get(self::UMOD . "/plugins/{$name}.json"), $batch, )); } catch (Throwable) { continue; } foreach ($batch as $name) { $response = $responses[$name] ?? null; if (!$response instanceof Response) { continue; } if ($response->status() === 404) { Cache::put("rust-plugins:umod:{$name}", false, 21600); } elseif ($response->successful() && ($hit = $this->hit((array) $response->json())) !== null && $hit['id'] === $name) { Cache::put("rust-plugins:umod:{$name}", $hit, 43200); $found[$name] = $hit; } } } return $found; } private function hit(mixed $plugin): ?array { if (!is_array($plugin) || !is_string($plugin['name'] ?? null) || preg_match(self::NAME, $plugin['name']) !== 1) { return null; } $https = fn (mixed $url) => is_string($url) && str_starts_with($url, 'https://') ? $url : null; return [ 'id' => $plugin['name'], 'name' => (string) ($plugin['title'] ?? $plugin['name']), 'description' => (string) ($plugin['description'] ?? ''), 'author' => (string) ($plugin['author'] ?? ''), 'icon' => $https($plugin['icon_url'] ?? null), 'url' => $https($plugin['url'] ?? null) ?? self::UMOD . '/plugins', 'downloads' => (int) ($plugin['downloads'] ?? 0), 'stars' => (int) ($plugin['watchers'] ?? 0), 'updatedAt' => $plugin['latest_release_at_atom'] ?? null, 'version' => is_string($plugin['latest_release_version'] ?? null) ? $plugin['latest_release_version'] : null, ]; } private function numeric(string $version): string { preg_match('/[0-9]+(?:\.[0-9]+)*/', $version, $match); return $match[0] ?? '0'; } private function error(string $code, string $detail, int $status): JsonResponse { return new JsonResponse(['errors' => [['code' => $code, 'status' => (string) $status, 'detail' => $detail]]], $status); } private function unreachable(): JsonResponse { return $this->error('CatalogueUnreachable', 'uMod could not be reached. Try again shortly.', 504); } private function notAPlugin(): JsonResponse { return $this->error('NotAPlugin', 'That is not a plugin in this folder.', 422); } } 